// Написан по плану и map-helpers.ts БЕЗ прогона на живой странице (MCP-генератор не нашёл seed) — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/location-map.md
// seed: tests/seed.free.geo.spec.ts
import { test, expect, type Response } from '@playwright/test';
import path from 'path';
import { disableSharing } from './map-helpers';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free.json'),
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  geolocation: { latitude: 32.0853, longitude: 34.7818, accuracy: 10 },
  permissions: ['geolocation'],
});

const isSharePatch = (r: Response) =>
  r.request().method() === 'PATCH' && r.url().includes('/rest/v1/profiles') && (r.request().postData() ?? '').includes('share_location');

test.describe('Местоположение и карта', () => {
  test('Включение шаринга → PATCH share_location=true, «אני» на карте, индикатор; выключение через пилюлю мгновенно @iphone @data (#2a31ff #46db57)', async ({ page }) => {
    // 1. Открыть /map; если шаринг включён — выключить (предусловие)
    await disableSharing(page);
    await expect(page.getByText('שיתוף מיקום כבוי')).toBeVisible();

    let shared = false;
    try {
      // 2. Нажать «הפעלת שיתוף מיקום», ожидая ответ PATCH /rest/v1/profiles
      const enablePatch = page.waitForResponse(isSharePatch);
      await page.getByRole('button', { name: 'הפעלת שיתוף מיקום' }).or(page.getByText('הפעלת שיתוף מיקום')).first().click();
      const enableRes = await enablePatch;
      shared = true;
      expect(enableRes.ok()).toBeTruthy();
      expect(enableRes.request().postDataJSON()).toMatchObject({ share_location: true });
      await expect(page.getByText('שיתוף מיקום פעיל')).toBeVisible();
      await expect(page.getByText('אני', { exact: true }).first()).toBeVisible();

      // 3. Перезагрузить карту, ожидая запрос /rpc/nearby_live (и /rpc/record_location, если идёт)
      const nearbyReq = page.waitForRequest((r) => r.method() === 'POST' && r.url().includes('/rpc/nearby_live'));
      await page.reload();
      const req = await nearbyReq;
      const nums = (JSON.stringify(req.postDataJSON() ?? {}).match(/-?\d+\.\d+/g) ?? []).map(Number);
      expect(nums.some((n) => Math.abs(n - 32.0853) <= 0.0005)).toBeTruthy();
      expect(nums.some((n) => Math.abs(n - 34.7818) <= 0.0005)).toBeTruthy();
      await expect(page.getByText('שיתוף מיקום פעיל')).toBeVisible();

      // 4. Нажать пилюлю «שיתוף מיקום פעיל»
      await page.getByText('שיתוף מיקום פעיל').click();
      await expect(page.getByText('לכבות את שיתוף המיקום?')).toBeVisible();
      await expect(page.getByText('כיבוי שיתוף מיקום', { exact: true })).toBeVisible();
      await expect(page.getByText('ביטול', { exact: true })).toBeVisible();

      // 5. В шторке нажать «כיבוי שיתוף מיקום», ожидая PATCH /rest/v1/profiles
      const disablePatch = page.waitForResponse(isSharePatch);
      await page.getByText('כיבוי שיתוף מיקום', { exact: true }).click();
      const disableRes = await disablePatch;
      expect(disableRes.request().postDataJSON()).toMatchObject({ share_location: false });
      shared = false;
      await expect(page.getByText('שיתוף מיקום כבוי')).toBeVisible();
      await expect(page.getByText('שיתוף מיקום פעיל')).toHaveCount(0);
    } finally {
      if (shared) await disableSharing(page);
    }
  });
});
